function solve(s, t) {
  if (s.length !== t.length) return false;
  const forward = new Map();
  const backward = new Map();
  for (let i = 0; i < s.length; i++) {
    const a = s[i];
    const b = t[i];
    if (forward.has(a)) {
      if (forward.get(a) !== b) return false;
    } else {
      forward.set(a, b);
    }
    if (backward.has(b)) {
      if (backward.get(b) !== a) return false;
    } else {
      backward.set(b, a);
    }
  }
  return true;
}
